package com.dreamseekers;

import com.dreamseekers.skill.*;
import com.dreamseekers.unit.BeetleUnit;
import com.mojang.authlib.GameProfile;
import com.solegendary.reignofnether.player.*;
import com.solegendary.reignofnether.registrars.*;
import com.solegendary.reignofnether.resources.*;
import com.solegendary.reignofnether.unit.*;
import com.solegendary.reignofnether.unit.goals.AbstractMeleeAttackUnitGoal;
import com.solegendary.reignofnether.unit.interfaces.*;
import net.minecraft.core.BlockPos;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.*;
import net.minecraft.server.network.ServerGamePacketListenerImpl;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.*;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.level.ChunkPos;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.phys.*;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.gametest.*;
import java.io.File;
import java.util.*;

/** Two ordinary JVM/world save cycles. Manifest has identities and expectations, never reconstructed bodies. */
@GameTestHolder("dreamseekers_beetle_advance_restart")
@PrefixGameTestTemplate(false)
public final class BeetleAdvanceSkillRestartGameTests {
    private static final String OWNER="BeetleAdvanceRestart_Owner",ENEMY="BeetleAdvanceRestart_Enemy";
    private static final BlockPos ORIGIN=new BlockPos(73728,90,73728);
    private static final File MANIFEST=new File("beetle-advance-skill-restart-expectations.nbt");
    private static final UUID MOVE_TECH=UUID.fromString("572b46a0-21ca-4e91-9ddd-afba33707380");
    private static final List<String> KEYS=List.of("spentStrike","unspentStrike","unusedCaster","victim");
    private static final Map<String,FakePlayer> PLAYERS=new HashMap<>();

    @GameTest(template="unit_isolation_arena",batch="dreamseekers_beetle_advance_restart",timeoutTicks=1450)
    public static void normalRestartKeepsPaidCooldownAndPermanentSpeedButNeverReplaysLiveOrUnspentFirstStrike(GameTestHelper h) throws Exception {
        switch(System.getProperty("dreamseekers.beetle.advance.test.phase","")){case "prepare"->prepare(h);case "verify"->verify(h);default->throw new IllegalArgumentException("Unknown beetle advance restart phase");}
    }
    private static void prepare(GameTestHelper h){
        ServerLevel level=h.getLevel();h.assertTrue(!MANIFEST.exists()&&PlayerServerEvents.getRTSPlayer(OWNER)==null&&PlayerServerEvents.getRTSPlayer(ENEMY)==null,"fresh isolated prepare world, never reuse an already consumed verification");CompoundTag expected=new CompoundTag();expected.putLong("prepareJvmStart",java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime());List<Long> forced=new ArrayList<>();for(int x=4608;x<=4609;x++)for(int z=4608;z<=4609;z++){long key=ChunkPos.asLong(x,z);h.assertTrue(!level.getForcedChunks().contains(key),"only new fixture chunk tickets");level.setChunkForced(x,z,true);forced.add(key);}expected.putLongArray("forcedChunks",forced);arena(level);for(String owner:List.of(OWNER,ENEMY)){PlayerServerEvents.rtsPlayers.add(RTSPlayer.getNewBot(owner,DreamseekersMod.DREAMSEEKERS));ResourcesServerEvents.resourcesList.add(new Resources(owner,123,234,345,456));player(level,owner);}
        Map<String,Mob> bodies=new LinkedHashMap<>();for(int i=0;i<3;i++){var beetle=DreamseekersMod.BEETLE.get().create(level);owned(h,beetle,OWNER,4,1,6+i*9,2001+i);damage(beetle,10);neutral(beetle);beetle.getAttribute(Attributes.MOVEMENT_SPEED).addPermanentModifier(new AttributeModifier(MOVE_TECH,"actual permanent restart movement research",.025,AttributeModifier.Operation.ADDITION));bodies.put(KEYS.get(i),beetle);}var victim=EntityRegistrar.ZOMBIE_UNIT.get().create(level);owned(h,victim,ENEMY,23,1,6,2004);neutral(victim);victim.getAttribute(Attributes.MAX_HEALTH).setBaseValue(1000);victim.setHealth(1000);bodies.put("victim",victim);for(var entry:bodies.entrySet())expected.putUUID(entry.getKey(),entry.getValue().getUUID());
        h.startSequence().thenWaitUntil(()->{for(Mob e:bodies.values())published(h,e);for(var p:PLAYERS.values())published(h,p);})
          .thenExecute(()->{ledger(h);var spent=(BeetleUnit)bodies.get("spentStrike");var unspent=(BeetleUnit)bodies.get("unspentStrike");h.assertTrue(cast(level,spent)==SkillResult.SUCCESS&&cast(level,unspent)==SkillResult.SUCCESS,"two actual owner-authenticated casts pay independent cooldowns");close(h,hit(h,spent,victim),13,"real installed goal spends first source's enhanced primary before save");h.assertTrue(BeetleAdvance.active(spent)&&!BeetleAdvance.firstStrikeAvailable(spent)&&BeetleAdvance.active(unspent)&&BeetleAdvance.firstStrikeAvailable(unspent),"both live speed states differ genuinely in consumed versus unconsumed first strike");position(spent,Vec3.atBottomCenterOf(at(4,1,6)));h.assertTrue(spent.distanceToSqr(victim)>100&&spent.getTarget()==null,"save has no lingering close attack target or auto-acquisition fixture hazard");})
          .thenIdle(10).thenExecute(()->{expected.putLong("snapshotGameTime",level.getGameTime());expected.putInt("oldLiveTicks",70);for(var entry:bodies.entrySet()){Mob e=entry.getValue();var u=(Unit)e;CompoundTag state=new CompoundTag();state.putFloat("health",e.getHealth());state.putInt("scenario",u.getScenarioRoleIndex());state.putString("owner",u.getOwnerName());state.putDouble("moveBase",e.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue());if(e instanceof BeetleUnit b){state.putLong("revision",b.rts().skills().revision());state.putInt("cooldown",cd(b));state.putDouble("moveWithPermanent",b.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue()+.025);if(!entry.getKey().equals("unusedCaster")){h.assertTrue(BeetleAdvance.remainingTicks(b)==70&&cd(b)==310,"ordinary save snapshot really contains seventy-tick active speed and paid310 cooldown");close(h,b.getAttributeValue(Attributes.MOVEMENT_SPEED),state.getDouble("moveWithPermanent")*1.25,"actual native speed is enhanced before ordinary shutdown save");}else h.assertTrue(cd(b)==0&&!BeetleAdvance.active(b),"third real source remains genuinely unused");}expected.put(entry.getKey()+"State",state);}h.assertTrue(BeetleAdvance.firstStrikeAvailable((BeetleUnit)bodies.get("unspentStrike"))&&!BeetleAdvance.firstStrikeAvailable((BeetleUnit)bodies.get("spentStrike")),"saved active sources retain their distinct live token states immediately before normal save");ledger(h);try{NbtIo.writeCompressed(expected,MANIFEST);}catch(Exception failure){throw new RuntimeException(failure);}System.out.println("DREAMSEEKERS_BEETLE_ADVANCE_RESTART_PREPARED time="+level.getGameTime()+" live70 spentCD310 UUIDs="+KEYS.stream().map(k->k+":"+bodies.get(k).getUUID()).toList());}).thenSucceed();
    }
    private static void verify(GameTestHelper h) throws Exception {
        ServerLevel level=h.getLevel();h.assertTrue(MANIFEST.isFile(),"prepare expectation manifest exists");CompoundTag expected=NbtIo.readCompressed(MANIFEST);h.assertTrue(expected.getLong("prepareJvmStart")!=java.lang.management.ManagementFactory.getRuntimeMXBean().getStartTime(),"actually a second JVM, not hand-NBT reconstruction in one process");for(long key:expected.getLongArray("forcedChunks")){h.assertTrue(level.getForcedChunks().contains(key),"ordinary world saved original fixture chunk ticket");var chunk=new ChunkPos(key);level.getChunk(chunk.x,chunk.z);}for(String name:List.of(OWNER,ENEMY))player(level,name);Map<String,Mob> bodies=new LinkedHashMap<>();long[] elapsedAtLoad={0};
        h.startSequence().thenWaitUntil(()->{for(String key:KEYS){Entity e=level.getEntity(expected.getUUID(key));h.assertTrue(e instanceof Mob,"ordinary world loader restored actual original UUID: "+key);published(h,e);}for(var p:PLAYERS.values())published(h,p);})
          .thenExecute(()->{long elapsed=level.getGameTime()-expected.getLong("snapshotGameTime");elapsedAtLoad[0]=elapsed;h.assertTrue(elapsed>=0&&elapsed<310,"second-JVM validation observes original paid cooldown before its natural deadline: "+elapsed);for(String key:KEYS){Mob e=(Mob)level.getEntity(expected.getUUID(key));bodies.put(key,e);var state=expected.getCompound(key+"State");var u=(Unit)e;h.assertTrue(u.getOwnerName().equals(state.getString("owner"))&&u.getScenarioRoleIndex()==state.getInt("scenario")&&UnitServerEvents.getAllUnits().stream().filter(b->b.getUUID().equals(e.getUUID())).count()==1,"normal original identity, owner, role and exactly-one roster entry survive: "+key);close(h,e.getHealth(),state.getFloat("health"),"normal save/load neither replayed attack nor introduced incidental hostile damage: "+key);close(h,e.getAttribute(Attributes.MOVEMENT_SPEED).getBaseValue(),state.getDouble("moveBase"),"native base movement unchanged: "+key);if(e instanceof BeetleUnit b){h.assertTrue(!BeetleAdvance.active(b)&&!BeetleAdvance.firstStrikeAvailable(b)&&BeetleAdvance.remainingTicks(b)==0,"neither consumed nor unspent transient token/speed restores from NBT: "+key);close(h,SkillEffects.bonus(b,BuffKind.MOVEMENT_SPEED),0,"no temporary speed contribution persisted");h.assertTrue(b.getAttribute(Attributes.MOVEMENT_SPEED).getModifier(MOVE_TECH)!=null,"exact permanent movement UUID survived");close(h,b.getAttributeValue(Attributes.MOVEMENT_SPEED),state.getDouble("moveWithPermanent"),"only actual permanent native modifier remains");int remain=(int)Math.max(0,state.getInt("cooldown")-elapsed);h.assertTrue(cd(b)==remain&&b.rts().skills().revision()>=state.getLong("revision"),"absolute CD/replay revision retained without refund or clock restart: "+key+" expected="+remain+" actual="+cd(b));}}
            var spent=(BeetleUnit)bodies.get("spentStrike");var unspent=(BeetleUnit)bodies.get("unspentStrike");var unused=(BeetleUnit)bodies.get("unusedCaster");var victim=bodies.get("victim");h.assertTrue(cast(level,spent)==SkillResult.COOLDOWN&&cast(level,unspent)==SkillResult.COOLDOWN,"both normally loaded paid casters reject free recast");close(h,hit(h,spent,victim),10,"real post-load goal cannot replay already consumed skill damage");close(h,hit(h,unspent,victim),10,"real post-load goal cannot replay saved but unspent first strike");close(h,hit(h,unused,victim),10,"unused normally loaded body has ordinary baseline before any fresh cast");h.assertTrue(cd(unused)==0&&cast(level,unused)==SkillResult.SUCCESS,"genuinely unused original source can make a new real post-restart authenticated cast");close(h,hit(h,unused,victim),13,"new actual cast alone grants a new enhanced installed-goal primary");close(h,hit(h,unused,victim),10,"fresh authority is consumed once, not duplicated by old save state");for(int i=0;i<3;i++)position(bodies.get(KEYS.get(i)),Vec3.atBottomCenterOf(at(4,1,6+i*9)));ledger(h);})
          .thenIdle(35).thenWaitUntil(()->h.assertTrue(level.getGameTime()>=expected.getLong("snapshotGameTime")+expected.getInt("oldLiveTicks"),"observe at or after real original pre-shutdown first-strike/speed deadline"))
          .thenExecute(()->{for(String key:List.of("spentStrike","unspentStrike")){var b=(BeetleUnit)bodies.get(key);h.assertTrue(!BeetleAdvance.active(b)&&!BeetleAdvance.firstStrikeAvailable(b)&&b.getTarget()==null,"old deadline never revives speed/token/target over current normal state: "+key);close(h,b.getAttributeValue(Attributes.MOVEMENT_SPEED),expected.getCompound(key+"State").getDouble("moveWithPermanent"),"no late temporary movement reapplication");long expiry=expected.getLong("snapshotGameTime")+expected.getCompound(key+"State").getInt("cooldown");h.assertTrue(cd(b)==Math.max(0,expiry-level.getGameTime()),"original paid absolute clock remains authoritative through old effect expiry");}ledger(h);System.out.println("DREAMSEEKERS_BEETLE_ADVANCE_RESTART_UUID_CD_NO_FIRST_STRIKE_REPLAY_PASS elapsedAtLoad="+elapsedAtLoad[0]+" finalElapsed="+(level.getGameTime()-expected.getLong("snapshotGameTime"))+" remainingCD="+cd((BeetleUnit)bodies.get("unspentStrike"))+" originalUUIDs="+KEYS.stream().map(k->bodies.get(k).getUUID()).toList());for(Mob e:bodies.values())e.discard();for(var p:PLAYERS.values())p.serverLevel().removePlayerImmediately(p,Entity.RemovalReason.DISCARDED);PLAYERS.clear();PlayerServerEvents.players.removeIf(p->List.of(OWNER,ENEMY).contains(p.getGameProfile().getName()));PlayerServerEvents.rtsPlayers.removeIf(p->List.of(OWNER,ENEMY).contains(p.name));ResourcesServerEvents.resourcesList.removeIf(r->List.of(OWNER,ENEMY).contains(r.ownerName));for(long key:expected.getLongArray("forcedChunks")){var chunk=new ChunkPos(key);level.setChunkForced(chunk.x,chunk.z,false);}}).thenSucceed();
    }
    private static SkillResult cast(ServerLevel level,BeetleUnit b){return SkillService.request(player(level,OWNER),new SkillRequest(UnitSkill.BEETLE_ADVANCE,b.getId(),b.getUUID(),b.rts().skills().revision(),b.getId(),b.getUUID()));}
    private static int cd(BeetleUnit b){return b.rts().skills().cooldownTicks(UnitSkill.BEETLE_ADVANCE);}
    private static void owned(GameTestHelper h,Mob e,String owner,int x,int y,int z,int scenario){h.assertTrue(e instanceof Unit,"real registered RTS fixture");var u=(Unit)e;u.setOwnerName(owner);u.setScenarioRoleIndex(scenario);e.setNoAi(true);e.getAttribute(AttributeRegistrar.AGGRO_RANGE.get()).setBaseValue(0);position(e,Vec3.atBottomCenterOf(at(x,y,z)));h.assertTrue(h.getLevel().addFreshEntity(e),"real body enters ordinary entity storage");}
    private static void damage(LivingEntity e,double amount){e.getAttribute(AttributeRegistrar.ATTACK_DAMAGE.get()).setBaseValue(amount);if(e.getAttribute(Attributes.ATTACK_DAMAGE)!=null)e.getAttribute(Attributes.ATTACK_DAMAGE).setBaseValue(amount);var crit=e.getAttribute(AttributeRegistrar.CRITICAL_HIT_CHANCE.get());if(crit!=null)crit.setBaseValue(0);}
    private static void neutral(LivingEntity e){e.getAttribute(Attributes.ARMOR).setBaseValue(0);e.getAttribute(Attributes.ARMOR_TOUGHNESS).setBaseValue(0);e.getAttribute(Attributes.KNOCKBACK_RESISTANCE).setBaseValue(1);e.setAbsorptionAmount(0);for(var a:List.of(AttributeRegistrar.MAGIC_DAMAGE_RESIST.get(),AttributeRegistrar.RANGED_DAMAGE_RESIST.get()))if(e.getAttribute(a)!=null)e.getAttribute(a).setBaseValue(0);}
    private static void position(Entity e,Vec3 p){e.moveTo(p.x,p.y,p.z);e.setDeltaMovement(Vec3.ZERO);}
    /** Actual installed native melee goal; no direct doHurtTarget or addon-ticket fabrication. */
    private static double hit(GameTestHelper h,BeetleUnit source,LivingEntity target){h.assertTrue(source.getAttackGoal() instanceof AbstractMeleeAttackUnitGoal,"original paid beetle still owns real installed native melee goal");var goal=(AbstractMeleeAttackUnitGoal)source.getAttackGoal();double gap=source.getBbWidth()/2+target.getBbWidth()/2+.1;position(source,target.position().add(-gap,0,0));source.setNoAi(true);source.setUnitAttackTargetForced(target);source.setHoldPosition(true);h.assertTrue(source.getTarget()==target&&!source.getBoundingBox().intersects(target.getBoundingBox())&&source.hasLineOfSight(target),"real nonoverlapping exact native melee stance");for(int i=0;i<(int)Math.ceil(source.getAttackCooldown())+2;i++)goal.tickAttackCooldown();target.invulnerableTime=0;float before=target.getHealth();goal.start();goal.tick();goal.stop();source.setUnitAttackTargetForced(null);return before-target.getHealth();}
    private static void published(GameTestHelper h,Entity e){h.assertTrue(e.tickCount>3&&h.getLevel().getEntity(e.getId())==e&&h.getLevel().getEntity(e.getUUID())==e,"actual original identity published with natural ticks: "+e.getUUID()+" ticks="+e.tickCount);}
    private static BlockPos at(int x,int y,int z){return ORIGIN.offset(x,y,z);}
    private static FakePlayer player(ServerLevel level,String name){return PLAYERS.computeIfAbsent(name,key->{var p=new FakePlayer(level,new GameProfile(UUID.nameUUIDFromBytes(key.getBytes(java.nio.charset.StandardCharsets.UTF_8)),key));p.connection=new SilentHandler(p);position(p,Vec3.atBottomCenterOf(at(key.equals(OWNER)?2:29,1,28)));level.addNewPlayer(p);PlayerServerEvents.players.add(p);return p;});}
    private static void ledger(GameTestHelper h){for(String owner:List.of(OWNER,ENEMY)){var r=ResourcesServerEvents.resourcesList.stream().filter(v->v.ownerName.equals(owner)).findFirst().orElse(null);h.assertTrue(r!=null,"original fixture bank exists; never recreate a lost account");h.assertTrue(r.food==123&&r.wood==234&&r.ore==345&&r.emerald==456&&r.foodToAdd==0&&r.woodToAdd==0&&r.oreToAdd==0&&r.emeraldToAdd==0,"strict original bank and all pending balances, no historical drift tolerance: "+owner);for(var e:UnitServerEvents.getAllUnits())if(e instanceof Unit u&&u.getOwnerName().equals(owner))h.assertTrue(u.getItems().isEmpty(),"declared empty cargo remains empty, not erased/rehydrated on save: "+e.getUUID()+" "+u.getItems());}System.out.println("BEETLE_ADVANCE_RESTART_LEDGER time="+h.getLevel().getGameTime()+" bothBanks=123,234,345,456 pending=0 cargo=empty");}
    private static void arena(ServerLevel level){for(int x=0;x<32;x++)for(int z=0;z<32;z++)level.setBlock(at(x,9,z),Blocks.STONE.defaultBlockState(),2);level.getEntitiesOfClass(net.minecraft.world.entity.item.FallingBlockEntity.class,new AABB(ORIGIN.getX(),ORIGIN.getY()+1,ORIGIN.getZ(),ORIGIN.getX()+32,level.getMaxBuildHeight(),ORIGIN.getZ()+32)).forEach(Entity::discard);for(int x=0;x<32;x++)for(int z=0;z<32;z++){level.setBlock(at(x,0,z),Blocks.STONE.defaultBlockState(),2);for(int y=1;y<9;y++)level.setBlock(at(x,y,z),(x==0||x==31||z==0||z==31?Blocks.STONE:Blocks.AIR).defaultBlockState(),2);}var drops=level.getEntitiesOfClass(ItemEntity.class,new AABB(ORIGIN,ORIGIN.offset(32,10,32)));System.out.println("BEETLE_ADVANCE_RESTART_CONSTRUCTION_DROPS count="+drops.size());drops.forEach(Entity::discard);}
    private static void close(GameTestHelper h,double actual,double expected,String why){h.assertTrue(Double.isFinite(actual)&&Math.abs(actual-expected)<.001,why+" expected="+expected+" actual="+actual);}
    private static final class SilentHandler extends ServerGamePacketListenerImpl{SilentHandler(ServerPlayer p){super(p.serverLevel().getServer(),new SilentConnection(),p);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
    private static final class SilentConnection extends net.minecraft.network.Connection{SilentConnection(){super(net.minecraft.network.protocol.PacketFlow.SERVERBOUND);}@Override public void tick(){}@Override public void send(net.minecraft.network.protocol.Packet<?> p){}@Override public void send(net.minecraft.network.protocol.Packet<?> p,net.minecraft.network.PacketSendListener listener){}}
}
